package config

import (
	"fmt"
	"io"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

// Config represents application configuration
type Config struct {
	Database DatabaseConfig `yaml:"database"`
	API      APIConfig      `yaml:"api"`
	Security SecurityConfig `yaml:"security"`
}

type DatabaseConfig struct {
	Host     string `yaml:"host"`
	Port     int    `yaml:"port"`
	User     string `yaml:"user"`
	PasswordEnv string `yaml:"password_env"` // Name of env var, not value
}

type APIConfig struct {
	Endpoint   string `yaml:"endpoint"`
	KeyEnv     string `yaml:"key_env"` // Name of env var, not value
	TimeoutSec int    `yaml:"timeout_sec"`
}

type SecurityConfig struct {
	TokenEnv string `yaml:"token_env"` // Name of env var, not value
}

// Loader reads YAML config from file path
type Loader struct {
	configPath string
}

// NewLoader creates a new config loader
func NewLoader(path string) *Loader {
	return &Loader{
		configPath: path,
	}
}

// Load reads config file and returns resolved configuration
// Credentials come ONLY from environment variables (via _env field references)
func (l *Loader) Load() (*Config, error) {
	// Validate path to prevent directory traversal
	absPath, err := filepath.Abs(l.configPath)
	if err != nil {
		return nil, fmt.Errorf("invalid config path: %w", err)
	}

	file, err := os.Open(absPath)
	if err != nil {
		return nil, fmt.Errorf("cannot open config file: %w", err)
	}
	defer file.Close()

	// Read file content
	data, err := io.ReadAll(file)
	if err != nil {
		return nil, fmt.Errorf("cannot read config file: %w", err)
	}

	// Unmarshal YAML
	var config Config
	if err := yaml.Unmarshal(data, &config); err != nil {
		return nil, fmt.Errorf("invalid YAML config: %w", err)
	}

	// Validate that environment variable names are specified (not values)
	if err := l.validateEnvReferences(&config); err != nil {
		return nil, err
	}

	return &config, nil
}

// validateEnvReferences ensures _env fields reference env var names, not secrets
func (l *Loader) validateEnvReferences(config *Config) error {
	if config.Database.PasswordEnv == "" {
		return fmt.Errorf("database.password_env must reference an environment variable")
	}
	if config.API.KeyEnv == "" {
		return fmt.Errorf("api.key_env must reference an environment variable")
	}
	if config.Security.TokenEnv == "" {
		return fmt.Errorf("security.token_env must reference an environment variable")
	}
	return nil
}

// GetDatabasePassword retrieves password from environment variable
// named in config (NOT from config file itself)
func (c *Config) GetDatabasePassword() (string, error) {
	envVarName := c.Database.PasswordEnv
	// Safely retrieve from environment only
	value := os.Getenv(envVarName)
	if value == "" {
		return "", fmt.Errorf("environment variable '%s' not set", envVarName)
	}
	return value, nil
}

// GetAPIKey retrieves API key from environment variable
func (c *Config) GetAPIKey() (string, error) {
	envVarName := c.API.KeyEnv
	value := os.Getenv(envVarName)
	if value == "" {
		return "", fmt.Errorf("environment variable '%s' not set", envVarName)
	}
	return value, nil
}

// GetSecurityToken retrieves token from environment variable
func (c *Config) GetSecurityToken() (string, error) {
	envVarName := c.Security.TokenEnv
	value := os.Getenv(envVarName)
	if value == "" {
		return "", fmt.Errorf("environment variable '%s' not set", envVarName)
	}
	return value, nil
}
