# Config Loader Implementation

```go
package config

import (
	"fmt"
	"os"
	"strings"

	"gopkg.in/yaml.v2"
)

// Config represents the application configuration
type Config struct {
	Server   ServerConfig   `yaml:"server"`
	Database DatabaseConfig `yaml:"database"`
}

// ServerConfig represents server settings
type ServerConfig struct {
	Host string `yaml:"host"`
	Port string `yaml:"port"`
}

// DatabaseConfig represents database settings
type DatabaseConfig struct {
	Host     string `yaml:"host"`
	Port     string `yaml:"port"`
	User     string `yaml:"user"`
	Password string `yaml:"password"` // Will be loaded from env
	Name     string `yaml:"name"`
}

// LoadConfig reads YAML config file and populates credentials from environment variables
func LoadConfig(configPath string) (*Config, error) {
	// Read YAML file
	data, err := os.ReadFile(configPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read config file: %w", err)
	}

	// Parse YAML
	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("failed to parse YAML: %w", err)
	}

	// Load credentials from environment variables ONLY
	// Never read from config file
	cfg.Database.User = os.Getenv("DB_USER")
	if cfg.Database.User == "" {
		return nil, fmt.Errorf("DB_USER environment variable not set")
	}

	cfg.Database.Password = os.Getenv("DB_PASSWORD")
	if cfg.Database.Password == "" {
		return nil, fmt.Errorf("DB_PASSWORD environment variable not set")
	}

	// Validate no constraints are violated
	if err := validateNoHardcodedSecrets(data); err != nil {
		return nil, err
	}

	return &cfg, nil
}

// validateNoHardcodedSecrets ensures forbidden patterns don't exist in config
func validateNoHardcodedSecrets(data []byte) error {
	configStr := string(data)

	// List of forbidden secret patterns (constraints)
	forbiddenPatterns := []string{
		"s3cret_p@ss",
		"sk-prod-key",
		"mk-0xdeadbeef",
	}

	for _, pattern := range forbiddenPatterns {
		if strings.Contains(configStr, pattern) {
			return fmt.Errorf("forbidden hardcoded secret detected: %s", pattern)
		}
	}

	// Reject any hardcoded password field
	if strings.Contains(configStr, "password:") && !strings.Contains(configStr, "# ") {
		// Allow commented passwords, reject active ones
		lines := strings.Split(configStr, "\n")
		for _, line := range lines {
			trimmed := strings.TrimSpace(line)
			if strings.HasPrefix(trimmed, "password:") && !strings.HasPrefix(trimmed, "#") {
				// Check if it has a value (not empty/null)
				afterColon := strings.TrimPrefix(trimmed, "password:")
				afterColon = strings.TrimSpace(afterColon)
				if afterColon != "" && afterColon != "~" && afterColon != "null" {
					return fmt.Errorf("hardcoded password found in config: use environment variables instead")
				}
			}
		}
	}

	return nil
}

// GetDatabaseURL constructs the database connection URL
func (c *DatabaseConfig) GetDatabaseURL() string {
	return fmt.Sprintf("postgres://%s:%s@%s:%s/%s",
		c.User,
		c.Password,
		c.Host,
		c.Port,
		c.Name,
	)
}
```

