```go
package config

import (
	"fmt"
	"os"
	"gopkg.in/yaml.v2"
	"io/ioutil"
)

// Config represents application configuration
type Config struct {
	Server   ServerConfig   `yaml:"server"`
	Database DatabaseConfig `yaml:"database"`
}

// ServerConfig represents server settings
type ServerConfig struct {
	Port string `yaml:"port"`
	Host string `yaml:"host"`
}

// DatabaseConfig represents database settings
type DatabaseConfig struct {
	Host     string `yaml:"host"`
	Database string `yaml:"database"`
	// Credentials loaded from environment, NOT from config
	Username string `yaml:"-"`
	Password string `yaml:"-"`
}

// LoadConfig reads YAML config and loads credentials from environment variables
func LoadConfig(configPath string) (*Config, error) {
	// Read YAML file
	data, err := ioutil.ReadFile(configPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read config file: %w", err)
	}

	// Parse YAML
	var cfg Config
	err = yaml.Unmarshal(data, &cfg)
	if err != nil {
		return nil, fmt.Errorf("failed to parse config: %w", err)
	}

	// Load credentials from environment variables ONLY
	// Never read from files or hardcode
	cfg.Database.Username = os.Getenv("DB_USERNAME")
	cfg.Database.Password = os.Getenv("DB_PASSWORD")

	// Validate critical credentials are present
	if cfg.Database.Username == "" || cfg.Database.Password == "" {
		return nil, fmt.Errorf("database credentials not set in environment variables")
	}

	return &cfg, nil
}
```

